// General shape
try {
    // code to be executed
}
catch (const exception1& e) { /* ... */ }
catch (const exception2& e) { /* ... */ }
catch (...)                  { /* must be LAST */ }

#include <iostream>

int main() {
    try {
        for (int tr = 0; tr < 10; ++tr) {
            if (tr == 5) throw "Reached 5";   // throws const char*
        }
    }
    catch (const char* msg) {
        std::cout << "Error: " << msg;        // "Error: Reached 5"
    }
    return 0;
}

// Sketch of the standard class
class exception {
public:
    virtual const char* what() const throw();
};

#include <exception>

struct DivisionBy0 : public std::exception {
    int value;
    DivisionBy0(int v) : value(v) {}
    const char* what() const noexcept override {
        return "Division by zero";
    }
};

double divide(int a, int b) {
    if (b == 0) throw DivisionBy0(a);
    return a / (double)b;
}

// Specifier (promise about the function)
int compute(int x) noexcept;            // never throws
int risky(int x)   noexcept(false);     // may throw (explicit)

// Operator (compile-time query about an expression)
static_assert(noexcept(compute(0)));    // ok
static_assert(!noexcept(risky(0)));     // ok

#include <iostream>
#include <new>   // for std::nothrow

int main() {
    int* x = new (std::nothrow) int[1000000000000];
    if (x == nullptr) {
        std::cout << "Unable to allocate memory!";
        return 1;
    }
    delete[] x;
    return 0;
}

